INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(3522000, 3522, 0, 1, 0, 0, 0, 0, 'Blade''s Edge Mountains', 'Barren plateaus, axe-cut valleys and forested tablelands, cut apart by crags bristling with knife-sharp spikes of stone. This was the homeland of the ogres, and it still is. Over them rule the hulking gronn, who show their lesser children no love at all.\n\nOrcs and ogres were enemies for generations. When the Horde rose, it conquered the ogre lands and broke the clans. Gul''dan experimented on captive ogres and made the first ogre magi, and the Horde drove the ogres before it as living siege engines.', 'warcraft.wiki.gg: Blade''s Edge Mountains (introduction, History, Rise of the Orcish Horde)'),
(3522001, 3522, 1, 1, 0, 0, 0, 0, 'Thunderlord Stronghold', 'The seat of the Thunderlord clan, abandoned when its orcs became fel orcs. The Bladespire ogres took the ruins; the Horde''s expedition drove them out and now holds it in honour of the clan that built it.', 'warcraft.wiki.gg: Thunderlord Stronghold'),
(3522002, 3522, 1, 2, 0, 0, 0, 0, 'Sylvanaar and Toshley''s Station', 'Sylvanaar is a night elf settlement with two moonwells, in the Living Grove above the Bloodmaul Ravine. Toshley''s gnomes lived there once, until the elves sent them away for the trouble their machines and experiments caused. They built their own station to the south-east.', 'warcraft.wiki.gg: Sylvanaar; warcraft.wiki.gg: Toshley''s Station'),
(3522003, 3522, 1, 3, 0, 0, 0, 0, 'Mok''Nathal Village', 'Before the orcs were corrupted, orcs and ogres sometimes had children together: the Mok''Nathal, honoured by shaman orcs as noble and savage creatures of the land, with an orc''s cunning and an ogre''s strength. Their village survives here. Among them is Leoroxx, father of Rexxar, the Champion of the Horde, who came back through the Portal looking for his own people.', 'warcraft.wiki.gg: Mok''Nathal Village; warcraft.wiki.gg: Blade''s Edge Mountains (Rise of the Orcish Horde); warcraft.wiki.gg: Thunderlord Stronghold'),
(3522004, 3522, 1, 4, 0, 0, 0, 0, 'The Ogre Clans', 'The Bladespire and the Bloodmaul fill the central valleys and raid each other''s camps. Gruul the Dragonkiller rules them both, and they worship him as a god. The Bloodmaul brew a beer taught them by a troll witch doctor, T''chali, whom they repaid by burying him up to his head in the ravine.', 'warcraft.wiki.gg: Bladespire Hold; warcraft.wiki.gg: Bloodmaul Outpost; warcraft.wiki.gg: Gruul''s Lair (Description)'),
(3522005, 3522, 1, 5, 0, 0, 0, 0, 'Dragons'' End', 'A cleft named for the four gigantic black dragons impaled on its peaks. Deathwing came to Draenor with the Horde and scattered his eggs across it, sure that nothing there would dare challenge his flight. Gruul dared. When Deathwing fled back to Azeroth, the dragons he left behind were torn from the sky by Bladespire spells and impaled by Gruul on the spires. That is how he earned his name.', 'warcraft.wiki.gg: Dragons'' End; warcraft.wiki.gg: Blade''s Edge Mountains (Beyond the Dark Portal)'),
(3522006, 3522, 1, 6, 0, 0, 0, 0, 'The Nether Drakes', 'Some of Deathwing''s eggs survived. When Draenor was torn apart, its wild nether energies washed over them, and they hatched into something new: the Netherwing. Their drakes nest among the singing crystals of the high ridges.', 'warcraft.wiki.gg: Blade''s Edge Mountains (Beyond the Dark Portal); warcraft.wiki.gg: Singing Ridge; warcraft.wiki.gg: Crystal Spine'),
(3522007, 3522, 1, 7, 0, 0, 0, 0, 'Ruuan Weald', 'A forested glade where the Cenarion Expedition keeps Evergrove, its only outpost manned almost entirely by night elves. The weald is overrun by the Wyrmcult, who serve the black dragonflight.', 'warcraft.wiki.gg: Ruuan Weald; warcraft.wiki.gg: Evergrove'),
(3522008, 3522, 1, 8, 0, 0, 0, 0, 'Ogri''la', 'A community of ogres who have risen above their brutish nature and the rule of the gronn, enlightened by the Apexis crystals. They fight the Legion and the black dragonflight for the crystals, with the Sha''tari Skyguard beside them. Other ogres speak of Ogri''la as a kind of promised land, and wonder if it is real.', 'warcraft.wiki.gg: Ogri''la (History); warcraft.wiki.gg: Skyguard Outpost'),
(3522009, 3522, 1, 9, 0, 0, 0, 0, 'The Forge Camps', 'The Legion holds three forge camps in the mountains, ringed with fel flak cannons against the Skyguard. At Death''s Door stands one of Magtheridon''s old gateways to the Twisting Nether. Illidan closed the others, but this one is still powered.', 'warcraft.wiki.gg: Forge Camp: Terror; warcraft.wiki.gg: Death''s Door'),
(3522010, 3522, 1, 10, 0, 0, 0, 0, 'The Arakkoa of Blade''s Edge', 'Ancient arakkoa tribes still live in these mountains: the Grishna, the Lashh''an, the Ruuan''ok and the Vekh''nir. The Vekh''nir have enslaved a tribe of ogres to dig draenethyst crystals out of the cave at Trogma''s Claim.', 'warcraft.wiki.gg: Blade''s Edge Mountains (History); warcraft.wiki.gg: Trogma''s Claim'),
(3522011, 3522, 1, 11, 0, 0, 0, 0, 'The Ethereal Camps', 'Ethereals have come to the mountains too. Nexus-Prince Razaan''s camp is full of floating spheres of mana and soul matter, with fleshbeasts crawling below, and his ethereals attack anyone on sight. Bash''ir''s band of the Ethereum holds a plateau on the Crystal Spine.', 'warcraft.wiki.gg: Razaan''s Landing; warcraft.wiki.gg: Bash''ir Landing'),
(3522012, 3522, 1, 12, 0, 0, 0, 0, 'Skald', 'Once wooded, burned to cinders when fire elementals and their imps moved in. The elementals still roam it, and they charge anyone who tries to bring green seeds back to the soil.', 'warcraft.wiki.gg: Skald'),
(3522013, 3522, 1, 13, 0, 0, 0, 0, 'The Circle of Blood', 'A great ogre-built arena in Daggermaw Canyon, where gladiators still fight.', 'warcraft.wiki.gg: Circle of Blood; warcraft.wiki.gg: Circle of Blood Arena'),
(3522030, 3522, 2, 1, 0, 0, 0, 0, 'The Sons of Gruul', 'Gruul''s powerful sons ravage the mountains and the plains of Nagrand, and hold the ogre clans under their fists.', 'warcraft.wiki.gg: Gruul''s Lair (Description); warcraft.wiki.gg: Ogri''la (History)');
